// Run this ONCE from the n8n editor ("Test step" on the Seed secrets trigger).
//
// Why here and not in the node parameters: whatever is written in a node body
// ends up in the exported JSON we commit. Static data does not — so the staff
// PIN and the session-signing secret exist only inside the running n8n instance.
//
// Set STAFF_PIN below, run the node once, then blank it out and save again.
// Re-running with a new PIN rotates it; rotating HMAC_SECRET signs every phone
// out immediately, which is the revocation lever from spec §12.3.

const STAFF_PIN = ''; // <- put the desk PIN here for one run, then clear it

const store = $getWorkflowStaticData('global');

if (STAFF_PIN) {
  store.pin = STAFF_PIN;
}
if (!store.hmacSecret) {
  const bytes = new Uint8Array(32);
  crypto.getRandomValues(bytes);
  store.hmacSecret = [...bytes].map((b) => b.toString(16).padStart(2, '0')).join('');
}

return [
  {
    json: {
      pin_set: Boolean(store.pin),
      hmac_secret_set: Boolean(store.hmacSecret),
      note: 'Clear STAFF_PIN from this node and save the workflow.',
    },
  },
];

const ALLOWED_ORIGIN = "https://mes178.github.io";
// Shared helpers, inlined into every Code node by scripts/build_workflows.py.
//
// Secrets (staff PIN, HMAC secret) live in this workflow's static data, seeded
// once by the "Seed secrets" manual trigger. They are therefore NOT in the
// exported JSON that gets committed — see docs/SETUP.md.

const EVENT_KEY = 'ls2026';
const SESSION_TTL_HOURS = 24;
const PIN_MAX_ATTEMPTS = 5;
const PIN_WINDOW_MS = 15 * 60 * 1000;

function secrets() {
  const store = $getWorkflowStaticData('global');
  if (!store.pin || !store.hmacSecret) {
    throw new Error('Secrets are not seeded. Run the "Seed secrets" trigger once.');
  }
  return store;
}

function b64url(bytes) {
  let binary = '';
  const arr = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  for (let i = 0; i < arr.length; i++) binary += String.fromCharCode(arr[i]);
  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function fromB64url(text) {
  const padded = text.replace(/-/g, '+').replace(/_/g, '/') + '==='.slice((text.length + 3) % 4);
  const binary = atob(padded);
  const out = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) out[i] = binary.charCodeAt(i);
  return out;
}

async function hmac(secret, message) {
  const enc = new TextEncoder();
  const key = await crypto.subtle.importKey(
    'raw',
    enc.encode(secret),
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign']
  );
  return new Uint8Array(await crypto.subtle.sign('HMAC', key, enc.encode(message)));
}

/** Compare two strings without leaking their difference through timing. */
function constantTimeEqual(a, b) {
  const x = String(a);
  const y = String(b);
  let diff = x.length ^ y.length;
  const len = Math.max(x.length, y.length);
  for (let i = 0; i < len; i++) diff |= (x.charCodeAt(i) || 0) ^ (y.charCodeAt(i) || 0);
  return diff === 0;
}

async function issueSession(device) {
  const payload = {
    device,
    issued_at: new Date().toISOString(),
    expires_at: new Date(Date.now() + SESSION_TTL_HOURS * 3600 * 1000).toISOString(),
  };
  const body = b64url(new TextEncoder().encode(JSON.stringify(payload)));
  const sig = b64url(await hmac(secrets().hmacSecret, body));
  return { token: `${body}.${sig}`, payload };
}

/** Returns the session payload, or null when the token is absent/forged/expired. */
async function verifySession(token) {
  if (!token || typeof token !== 'string' || !token.includes('.')) return null;
  const [body, sig] = token.split('.');
  let expected;
  try {
    expected = b64url(await hmac(secrets().hmacSecret, body));
  } catch (_) {
    return null;
  }
  if (!constantTimeEqual(sig, expected)) return null;
  let payload;
  try {
    payload = JSON.parse(new TextDecoder().decode(fromB64url(body)));
  } catch (_) {
    return null;
  }
  if (!payload.expires_at || new Date(payload.expires_at).getTime() < Date.now()) return null;
  return payload;
}

const CORS = {
  'Access-Control-Allow-Origin': ALLOWED_ORIGIN,
  'Access-Control-Allow-Headers': 'Content-Type, X-Session-Token',
  'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
  'Access-Control-Max-Age': '86400',
};

function reply(statusCode, body) {
  return [{ json: { statusCode, headers: CORS, body } }];
}

/** Case-insensitive header lookup — proxies normalise header case differently. */
function header(headers, name) {
  const wanted = name.toLowerCase();
  for (const key of Object.keys(headers || {})) {
    if (key.toLowerCase() === wanted) return headers[key];
  }
  return undefined;
}

// WF-C — POST /webhook/ls2026/auth   { pin, device } -> { session_token, expires_at }
//
// Rate limited per source IP: 5 attempts / 15 minutes (spec §10, §12.4).

const req = $input.first().json;
const method = (req.method || 'POST').toUpperCase();
if (method === 'OPTIONS') return reply(204, {});

const body = req.body || {};
const headers = req.headers || {};
const ip = header(headers, 'x-forwarded-for') || header(headers, 'x-real-ip') || 'unknown';
const device = String(body.device || '').trim().slice(0, 40);
const pin = String(body.pin || '');

// Throwing here would surface to the phone as an empty 200, which reads like a
// broken scanner rather than an unconfigured server.
let configured;
try {
  configured = secrets();
} catch (_) {
  return reply(503, { message: 'Check-in server is not configured yet. Seed the staff PIN in n8n.' });
}

const store = $getWorkflowStaticData('global');
store.pinAttempts = store.pinAttempts || {};

const now = Date.now();
const record = store.pinAttempts[ip] || { count: 0, first: now };
if (now - record.first > PIN_WINDOW_MS) {
  record.count = 0;
  record.first = now;
}

if (record.count >= PIN_MAX_ATTEMPTS) {
  store.pinAttempts[ip] = record;
  return reply(429, { message: 'Too many attempts. Wait 15 minutes.' });
}

if (!device) return reply(400, { message: 'Device label is required.' });

if (!constantTimeEqual(pin, configured.pin)) {
  record.count += 1;
  store.pinAttempts[ip] = record;
  return reply(401, { message: 'Wrong PIN.' });
}

delete store.pinAttempts[ip];

// Housekeeping: drop attempt records older than the window so the bag cannot
// grow without bound across the event.
for (const [key, value] of Object.entries(store.pinAttempts)) {
  if (now - value.first > PIN_WINDOW_MS) delete store.pinAttempts[key];
}

const session = await issueSession(device);
return reply(200, {
  session_token: session.token,
  expires_at: session.payload.expires_at,
  device,
  event_key: EVENT_KEY,
});

